        table: '<path d="M2.5 3h13v12h-13zM2.5 7h13M2.5 11h13M7 3v12"/>',
        book: '<path d="M9 4.5C7.5 3.3 5.2 3 2.5 3.2v11C5.2 14 7.5 14.4 9 15.5c1.5-1.1 3.8-1.5 6.5-1.3v-11C12.8 3 10.5 3.3 9 4.5zM9 4.5v11"/>',
