            const укорочены = h('input', { type: 'text', value: з.укорочены, placeholder: 'по стандарту', class: 'stol-md-table', 'aria-label': 'Укороченные позиции' });
            const перемежение = h('select', { 'aria-label': 'Перемежение бит' },
                видыПеремеженияLDPC().map(([v, т]) => h('option', { value: v, selected: v === з.перемежение }, т)));
            // Граница слова и вид потока — у каждого массива свои: не запоминаются, их ставит «Найти по встроенным».
            const начало = h('input', { type: 'number', min: 0, value: '', placeholder: 'само', class: 'stol-md-num', 'aria-label': 'Начало слова' });
            const шаг = h('input', { type: 'number', min: 0, value: '', placeholder: 'подряд', class: 'stol-md-num', 'aria-label': 'Шаг слов' });
            const смещения = h('input', { type: 'text', value: '', placeholder: '0', class: 'stol-md-table', 'aria-label': 'Смещения слов в периоде' });
            const рандомизатор = h('input', { type: 'checkbox' });
            const входИнверсия = h('input', { type: 'checkbox' });
            const входРеверс = h('input', { type: 'checkbox' });
            const plframe = h('select', { 'aria-label': 'PLFRAME DVB-S2' }, [['', 'нет'], ['да', 'снять заголовки'],
                ['скремблер', '+ скремблер PL']].map(([v, т]) => h('option', { value: v }, т)));
            // Заголовок PLFRAME в разметке данных (8PSK/QPSK): метки точек — как в «метки ТАБЛИЦА» слоя.
