                if (т && т.блоки) т.блоки.forEach((b) => блок.appendChild(h('option', { value: String(b) }, b + ' бит данных')));
                if (т && т.блоки) блок.value = т.блоки.map(String).includes(String(было)) ? String(было) : String(т.блоки[0]);
