                if (с.режимМетки && e.shiftKey && !e.altKey && вбок) ширинаПоля(с.ширинаМетки + вправо * (ctrl ? 8 : 1));
                else if (ctrl && (e.key === '+' || e.key === '=' || код === 'NumpadAdd')) приблизить(1);
                else if (ctrl && (e.key === '-' || код === 'NumpadSubtract')) приблизить(-1);
                else if (ctrl && e.key === 'F8') окноРазметкиПоПериоду(у);
                else if (ctrl && e.key === 'Home') указатель(0, e.shiftKey);
                else if (ctrl && e.key === 'End') указатель(n - 1, e.shiftKey);
                else if (ctrl && вбок) указатель(курсор() + вправо * (с.режимМетки ? с.ширинаМетки : 8), e.shiftKey);
